(function(root){
  'use strict';
  const core=root.treasureCore, KEY=core.KEY;
  const modes={normal:'普通藏宝图',advanced:'高级藏宝图'},sources={direct:'直接挖出',battle:'后续战斗',clue:'线索宝箱',other:'其他附加'};
  const maps=['未分类','傲来国','五庄观','建邺城','东海湾','江南野外','大唐国境','大唐境外','长寿郊外','花果山','北俱芦洲','普陀山','女儿村','狮驼岭','朱紫国','麒麟山','墨家村'];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>Number(n.toFixed(4)).toLocaleString('zh-CN',{maximumFractionDigits:4});
  function itemImage(item,extra=''){
    const resolver=root.itemIcons||root.treasureIcons;let info;
    try{if(typeof resolver?.resolve==='function')info=resolver.resolve(item);}catch(_){}
    const name=String(item.name||item.category||item.kind||'物品'),src=typeof info?.src==='string'&&info.src?info.src:'./icons/其他.png',kind=info?.kind||'fallback';
    const title=name+(kind==='asset'?'':' · 通用分类图标，非专属外观')+(info?.label?' · '+info.label:'');
    return `<img class="tr-item-image ${esc(extra)}" src="${esc(src)}" alt="${esc(name)}" title="${esc(title)}" data-icon-kind="${esc(kind)}" loading="lazy" decoding="async">`;
  }
  const clone=v=>JSON.parse(JSON.stringify(v));
  const uid=prefix=>prefix+'-'+Date.now()+'-'+Math.random().toString(36).slice(2);
  let page,state,view='run',quickSource='direct',filter={mode:'',map:'',date:''};
  const d=()=>state.drafts[state.mode];
  const priceKey=(name,source)=>JSON.stringify([state.mode,name,source]);
  const priceLabels={fixed:'固定价物品',custom:'自定义价物品',cash:'现金收入'};
  function referenceItem(item){const {priceMode,...identity}=item;return identity;}
  function reference(item,source=quickSource,next=state){
    const key=JSON.stringify([next.mode,item.name,source]),legacy=next.prices[key];
    try{const shared=root.itemPrices,identity=referenceItem(item);if(shared?.describe(identity).shareable&&shared.has(identity))return {price:shared.get(identity),known:true,shared:true};}catch(_){}
    return {price:legacy===undefined?0:legacy,known:legacy!==undefined,shared:false};
  }
  function referenceText(item){const ref=reference(item);return item.cash?'填写实际现金金额':!ref.known?'未设价 · 添加后填价':money(ref.price)+' 万／个';}
  function refreshReferences(){if(!page||!state)return;const catalog=items();page.querySelectorAll('[data-add]').forEach(button=>{const item=catalog.find(x=>x.id===button.dataset.add),label=button.querySelector('small');if(item&&label)label.textContent=referenceText(item);});}
  function publishPrice(item,price){
    try{const shared=root.itemPrices,identity=referenceItem(item);if(shared?.describe(identity).shareable)shared.set(identity,price);}
    catch(e){tell('明细已保存；共享参考价未更新：'+e.message,true);}
  }
  function read(){return core.validateState(JSON.parse(localStorage.getItem(KEY)||'null')||core.empty());}
  function tell(message,error=false){const el=page.querySelector('[data-treasure-status]');el.textContent=message;el.classList.toggle('tr-error',error);}
  function update(fn,{sync=false,redraw=true,message=''}={}){try{const next=clone(state);fn(next);core.validateState(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;if(sync)root.dispatchEvent(new CustomEvent('ring-ledger-changed'));if(redraw)render();else refreshSummary();if(message)tell(message);return true;}catch(e){tell('未保存：'+e.message,true);return false;}}
  function num(value,label,integer=false){const n=Number(value);if(String(value).trim()===''||!Number.isFinite(n)||n<0||n>1e9||(integer&&!Number.isInteger(n)))throw new Error(label+'格式不正确');return n;}
  function metrics(t,aggregate=false){return `<div class="tr-metrics">${[['总成本',t.expense],['产出估值',t.revenue],['已到账收入',t.actualRevenue],['估值净收益',t.profit],['已到账收支',t.actualProfit]].map(([label,n])=>`<div><span>${label}</span><strong class="${n<0?'tr-negative':''}">${money(n)}<small> 万</small></strong></div>`).join('')}</div>${aggregate?'':`<div class="tr-kpis"><span>每张估值净收益 <b>${t.perMap===null?'—':money(t.perMap)+' 万'}</b></span><span>每小时估值净收益 <b>${t.perHour===null?'—':money(t.perHour)+' 万'}</b></span><span>未售物品估值 <b>${money(t.unrealized)} 万</b></span><span>事件 <b>${t.eventCount} 次</b></span></div>`}`;}
  function refreshSummary(){refreshCost(false);const summary=page.querySelector('.tr-extra-meta summary');if(summary)summary.textContent='更多'+(d().extraCost?' · 额外费用 '+money(d().extraCost)+' 万':'');}
  function refreshCost(persist=false){
    const priceInput=page.querySelector('[data-field="unitCost"]'),quantityInput=page.querySelector('[data-field="quantity"]'),output=page.querySelector('[data-treasure-total]');
    if(!priceInput||!quantityInput||!output)return true;
    output.textContent='—';
    if(priceInput.value.trim()===''||quantityInput.value.trim()===''){if(persist)tell('请填写单价和数量');return false;}
    try{
      const price=num(priceInput.value,'单价'),quantity=num(quantityInput.value,'数量',true);
      if(quantity>1000000)throw new Error('数量最多为 1,000,000 张');
      const amount=core.units(price,'单价')*quantity;
      if(!Number.isSafeInteger(amount))throw new Error('总价过大，请减少单价或数量');
      if(persist&&!update(s=>{s.drafts[s.mode].unitCost=price;s.drafts[s.mode].quantity=quantity;},{redraw:false})){output.textContent='—';return false;}
      output.textContent=money(amount/10000)+' 万';
      if(persist)tell('');
      return true;
    }catch(e){if(persist)tell(e.message,true);return false;}
  }
  function field(label,key,value,type='text',attrs=''){return `<label>${label}<input type="${type}" data-field="${key}" value="${esc(value)}" ${attrs}></label>`;}
  function items(){return [...core.catalogs(state.mode),...state.customItems.filter(x=>x.mode===state.mode||x.mode==='both')];}
  function groupSummary(mode,group){return `<strong>${priceLabels[mode]}</strong><span data-breakdown-quantity>${group.quantity} ${mode==='cash'?'笔':'件'}</span><span>${mode==='cash'?'金额':'估值'} <b data-breakdown-revenue>${money(group.revenue)}</b> 万</span><span>到账 <b data-breakdown-actual>${money(group.actualRevenue)}</b> 万</span>`;}
  function breakdownSummary(records){const sum={};for(const mode of core.PRICE_MODES)sum[mode]={quantity:0,revenue:0,actualRevenue:0};for(const rec of records){const parts=core.priceBreakdown(rec);for(const mode of core.PRICE_MODES){const total=sum[mode],group=parts[mode];total.quantity+=group.quantity;total.revenue+=group.revenueUnits;total.actualRevenue+=group.actualRevenueUnits;}}for(const group of Object.values(sum)){group.revenue/=10000;group.actualRevenue/=10000;}return `<div class="tr-price-summary" data-price-summary>${core.PRICE_MODES.map(mode=>`<div data-price-subtotal="${mode}">${groupSummary(mode,sum[mode])}</div>`).join('')}</div>`;}
  function rowMarkup(r,i,editable){return `<tr data-price-row="${core.rowPriceMode(r)}"><td><div class="tr-name-cell">${itemImage(r,'tr-row-image')}<div class="tr-name-text">${editable?`<input data-row="${i}" data-prop="name" value="${esc(r.name)}" maxlength="100" aria-label="物品名称">`:esc(r.name)}<small>${esc(r.category)}${r.cash?' · 现金':''}</small></div></div></td><td>${editable?`<select data-row="${i}" data-prop="source" aria-label="产出来源">${Object.entries(sources).map(([id,label])=>`<option value="${id}" ${r.source===id?'selected':''}>${label}</option>`).join('')}</select>`:sources[r.source]}</td><td>${editable?`<input data-row="${i}" data-prop="quantity" type="number" min="1" max="100000" step="1" value="${r.quantity}" ${r.cash?'readonly':''} aria-label="物品数量">`:r.quantity}</td><td>${editable?`<input data-row="${i}" data-prop="price" type="number" min="0" max="1000000000" step="0.0001" value="${r.price}" aria-label="物品单价">`:money(r.price)}</td><td>${money(core.units(r.price)*r.quantity/10000)}</td><td>${editable?`<label class="tr-check"><input data-row="${i}" data-prop="realized" type="checkbox" ${r.realized?'checked':''} ${r.cash?'disabled':''}>${r.cash?'现金':'已售'}</label>`:(r.realized?'已到账':'未售估值')}</td>${editable?`<td><button data-action="remove-row" data-index="${i}">移除</button></td>`:''}</tr>`;}
  function rowsTable(record,editable=false){const parts=core.priceBreakdown(record);return `<div class="tr-scroll"><table><thead><tr><th>物品</th><th>来源</th><th>数量</th><th>单价/万</th><th>总价/万</th><th>到账</th>${editable?'<th>操作</th>':''}</tr></thead>${core.PRICE_MODES.map(mode=>`<tbody data-price-group="${mode}"><tr class="tr-price-group"><td colspan="${editable?7:6}"><div data-price-subtotal="${mode}">${groupSummary(mode,parts[mode])}</div></td></tr>${parts[mode].indexes.map(i=>rowMarkup(record.rows[i],i,editable)).join('')}</tbody>`).join('')}${record.rows.length?'':`<tbody><tr><td colspan="${editable?7:6}" class="tr-empty">还没有产出，点击左侧物品添加。</td></tr></tbody>`}</table></div>`;}
  function quickGroups(catalog){return core.PRICE_MODES.map(mode=>{const group=catalog.filter(item=>core.rowPriceMode(item)===mode);return group.length?`<div class="tr-quick-group" data-quick-group="${mode}"><h3>${priceLabels[mode]}</h3><div class="tr-quick">${group.map(item=>`<button data-add="${esc(item.id)}" data-price-mode="${mode}">${itemImage(item,'tr-quick-image')}<span>${esc(item.name)}</span><small>${referenceText(item)}</small></button>`).join('')}</div></div>`:'';}).join('');}
  function running(){const rec=d(),catalog=items();return `<div class="tr-cost-bar"><label class="tr-inline">单价（万）<input type="number" data-field="unitCost" value="${rec.unitCost}" min="0" max="1000000000" step="0.0001" aria-label="藏宝图单价（万）"></label><label class="tr-inline">数量（张）<input type="number" data-field="quantity" value="${rec.quantity}" min="0" max="1000000" step="1" aria-label="藏宝图数量（张）"></label><span class="tr-total">总价 <output data-treasure-total aria-live="polite">${money(core.units(rec.unitCost)*rec.quantity/10000)} 万</output></span>${rec.id?'<span class="tr-editing">正在修改历史</span>':''}</div><details class="tr-extra-meta"><summary>更多${rec.extraCost?' · 额外费用 '+money(rec.extraCost)+' 万':''}</summary><div class="tr-fields">${field('挖图日期','date',rec.date,'date')}${field('角色／队伍','role',rec.role,'text','maxlength="100" placeholder="可留空"')}${field('地图','map',rec.map,'text','list="treasure-maps" maxlength="100"')}${field('额外成本（万）','extraCost',rec.extraCost,'number','min="0" step="0.0001"')}${field('耗时（分钟）','minutes',rec.minutes,'number','min="0" step="1"')}${field('备注','notes',rec.notes,'text','maxlength="500" placeholder="自打图可按零成本或估值填写"')}</div><datalist id="treasure-maps">${maps.map(m=>`<option value="${esc(m)}">`).join('')}</datalist><p class="tr-hint">总价只计算单价×数量；额外费用在结算时另行扣除。未售只计估值，已到账收入减本轮成本自动合并总账。已包含在角色金币差额中的收入，请勿重复录入。</p></details><div class="tr-split"><section class="tr-item-pane"><div class="tr-section-head"><h2>产出快捷添加</h2><label class="tr-inline">来源<select data-quick-source>${Object.entries(sources).map(([id,label])=>`<option value="${id}" ${quickSource===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="tr-item-scroll">${quickGroups(catalog)}<details class="tr-custom"><summary>管理自定义快捷物品</summary><form data-form="custom" class="tr-fields"><label>名称<input name="name" maxlength="100" required placeholder="例如：吸血、连击、60项链书"></label><label>类别<input name="category" maxlength="50" value="自定义物品" required></label><label>适用<select name="mode"><option value="${state.mode}">仅${modes[state.mode]}</option><option value="both">普通图和高级图</option></select></label><button>保存为快捷物品</button></form><div class="tr-custom-list">${state.customItems.map(item=>`<span>${itemImage(item,'tr-custom-image')}${esc(item.name)} <small>${item.mode==='both'?'两种图':modes[item.mode]}</small> <button data-remove-custom="${esc(item.id)}">移除快捷项</button></span>`).join('')||'<p class="tr-hint">暂无自定义快捷项。</p>'}</div><p class="tr-hint">移除快捷项不会删除草稿或历史中的同名产出；价格随录入自动记忆。</p></details></div></section><section class="tr-record-pane"><h2>本轮物品与现金</h2>${rowsTable(rec,true)}<div class="tr-record-tools"><details class="tr-add-more"><summary>添加具体物品／附加收益</summary><form data-form="row" class="tr-fields"><label>物品名称<input name="name" maxlength="100" required placeholder="如：偷袭、迅敏、70级项链书"></label><label>类别<input name="category" maxlength="50" value="自定义物品" required></label><label>来源<select name="source">${Object.entries(sources).map(([id,label])=>`<option value="${id}" ${quickSource===id?'selected':''}>${label}</option>`).join('')}</select></label><label>数量<input name="quantity" type="number" min="1" max="100000" step="1" value="1" required></label><label>单价（万）<input name="price" type="number" min="0" step="0.0001" value="0" required></label><label class="tr-check"><input type="checkbox" name="realized">已售／已到账</label><label class="tr-check"><input type="checkbox" name="cash">现金收入</label><button>添加明细</button></form><p class="tr-hint">现金请数量填 1、单价填写收到的万梦幻币金额，自动按已到账处理。</p></details><details class="tr-events-panel"><summary>挖图事件（${core.totals(rec).eventCount} 次）</summary><div class="tr-events">${(core.EVENTS[state.mode]||[]).map(name=>`<button data-event="${esc(name)}">${esc(name)} <b>+1</b></button>`).join('')}</div><div class="tr-event-list">${rec.events.map((event,i)=>`<span>${esc(event.name)} <b>${event.count} 次</b><button aria-label="减少${esc(event.name)}一次" data-action="event-minus" data-index="${i}">−</button></span>`).join('')||'<p class="tr-hint">还没有记录事件。</p>'}</div></details></div><div class="tr-bottom"><span>估值净收益 ${money(core.totals(rec).profit)} 万<br>到账收支 ${money(core.totals(rec).actualProfit)} 万</span>${rec.id?'<button data-action="cancel-edit">取消修改历史</button>':''}<button data-action="settle" class="tr-primary">${rec.id?'保存历史修改并更新总账':'结算本轮并合并总账'}</button></div></section></div>`;}
  function filtered(){return state.history.filter(r=>(!filter.mode||r.mode===filter.mode)&&(!filter.map||r.map===filter.map)&&(!filter.date||r.date===filter.date));}
  function history(){const records=filtered(),sums={expense:0,revenue:0,actualRevenue:0,profit:0,actualProfit:0};let quantity=0;const grouped={};records.forEach(rec=>{const t=core.totals(rec);quantity+=rec.quantity;Object.keys(sums).forEach(k=>sums[k]=Math.round((sums[k]+t[k])*10000)/10000);const key=rec.mode+'|'+rec.map,g=grouped[key]||(grouped[key]={mode:rec.mode,map:rec.map,count:0,quantity:0,revenue:0,expense:0,actualRevenue:0,minutes:0});g.count++;g.quantity+=rec.quantity;g.revenue+=t.revenue;g.expense+=t.expense;g.actualRevenue+=t.actualRevenue;g.minutes+=rec.minutes;});return `<section><div class="tr-section-head"><h2>挖图历史与统计</h2><span>共 ${records.length} 轮 · ${quantity} 张图</span></div><div class="tr-fields"><label>宝图类型<select data-filter="mode"><option value="">全部类型</option>${Object.entries(modes).map(([key,label])=>`<option value="${key}" ${filter.mode===key?'selected':''}>${label}</option>`).join('')}</select></label><label>地图<select data-filter="map"><option value="">全部地图</option>${[...new Set(state.history.map(r=>r.map))].map(map=>`<option ${filter.map===map?'selected':''}>${esc(map)}</option>`).join('')}</select></label><label>日期<input type="date" data-filter="date" value="${esc(filter.date)}"></label><button data-action="clear-filter">清除筛选</button></div>${metrics(sums,true)}${breakdownSummary(records)}</section><section><h2>按地图统计</h2><div class="tr-scroll"><table><thead><tr><th>宝图类型</th><th>地图</th><th>轮数／张数</th><th>产出估值（万）</th><th>成本（万）</th><th>估值净收益（万）</th><th>每张估值净收益</th><th>每小时估值净收益</th></tr></thead><tbody>${Object.values(grouped).map(g=>`<tr><td>${modes[g.mode]}</td><td>${esc(g.map)}</td><td>${g.count} 轮／${g.quantity} 张</td><td>${money(g.revenue)}</td><td>${money(g.expense)}</td><td>${money(g.revenue-g.expense)}</td><td>${g.quantity?money((g.revenue-g.expense)/g.quantity):'—'}</td><td>${g.minutes?money((g.revenue-g.expense)*60/g.minutes):'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="tr-empty">结算本轮后，统计会显示在这里。</td></tr>'}</tbody></table></div></section><section><h2>历史明细</h2>${records.map(rec=>{const t=core.totals(rec),parts=core.priceBreakdown(rec);return `<details class="tr-history"><summary><span>${esc(rec.date)} · ${modes[rec.mode]} · ${esc(rec.map)} · ${rec.quantity} 张<small class="tr-history-parts">固定价 ${money(parts.fixed.revenue)} · 自定义价 ${money(parts.custom.revenue)} · 现金 ${money(parts.cash.revenue)} 万</small></span><strong class="${t.profit<0?'tr-negative':''}">估值净收益 ${money(t.profit)} 万</strong></summary><p>${esc(rec.role)||'未填写角色'} · 耗时 ${rec.minutes} 分钟 · 已到账收支 ${money(t.actualProfit)} 万</p><p>${esc(rec.notes)}</p>${rowsTable(rec)}<p class="tr-hint">事件：${rec.events.map(e=>esc(e.name)+' '+e.count+' 次').join('、')||'未登记'}</p><button data-action="edit" data-id="${esc(rec.id)}">修改／登记卖出</button> <button data-action="delete" data-id="${esc(rec.id)}">删除本轮</button></details>`;}).join('')||'<p class="tr-empty">没有符合筛选条件的记录。</p>'}</section>`;}
  function backup(){return `<section><h2>挖图数据备份</h2><p>包含普通图／高级图草稿、全部历史、自定义快捷物品和记忆单价。建议修改前先导出备份。</p><div class="tr-actions"><button data-action="export">导出挖图备份</button><button data-action="import">恢复挖图备份</button><input type="file" accept=".json" data-import hidden></div><p class="tr-hint">恢复会替换本模块现有数据，并重新计算五开总账中的挖图收支。不会改写原有手工记账、跑环或场景记录。</p></section>`;}
  function render(){const scroll=page.scrollTop,panes=Array.from(page.querySelectorAll('.tr-item-scroll,.tr-record-pane>.tr-scroll,.tr-record-tools')).map(el=>({kind:el.className,top:el.scrollTop,left:el.scrollLeft})),opened=Array.from(page.querySelectorAll('details[open]')).map(el=>el.className);page.classList.toggle('tr-run',view==='run');page.innerHTML=`<nav><h1>挖图记账</h1><div class="tr-modes">${Object.entries(modes).map(([mode,label])=>`<button data-mode="${mode}" aria-pressed="${state.mode===mode}">${label}</button>`).join('')}</div><div>${[['run','本轮'],['history','历史统计'],['backup','备份']].map(([key,label])=>`<button data-view="${key}" aria-pressed="${view===key}">${label}</button>`).join('')}</div><button data-shared-prices-open>统一价格</button><button data-action="back" class="tr-back">返回记账</button></nav><div role="status" aria-live="polite" data-treasure-status class="tr-status"></div><main>${view==='run'?running():view==='history'?history():backup()}</main>`;for(const name of opened){const panel=Array.from(page.querySelectorAll('details')).find(el=>el.className===name);if(panel)panel.open=true;}for(const position of panes){const pane=Array.from(page.querySelectorAll('.tr-item-scroll,.tr-record-pane>.tr-scroll,.tr-record-tools')).find(el=>el.className===position.kind);if(pane){pane.scrollTop=position.top;pane.scrollLeft=position.left;}}page.scrollTop=scroll;refreshCost(false);}
  function append(next,item,{source=quickSource,quantity=1,price,realized=false,cash=false}={}){
    const draft=next.drafts[next.mode],key=JSON.stringify([next.mode,item.name,source]),unit=price===undefined?reference(item,source,next).price:price;
    const priceMode=core.rowPriceMode({...item,cash}),existing=draft.rows.find(r=>r.name===item.name&&r.category===item.category&&r.source===source&&r.price===unit&&r.realized===(realized||cash)&&r.cash===cash&&core.rowPriceMode(r)===priceMode);
    if(existing){existing.priceMode=priceMode;existing.quantity+=quantity;}
    else draft.rows.push({id:uid('row'),name:item.name,category:item.category,source,quantity,price:unit,priceMode,realized:realized||cash,cash});
    if(price!==undefined)next.prices[key]=unit;
  }
  function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='挖图记账备份-'+new Date().toLocaleDateString('sv-SE')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function bind(){
    page.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
      if(b.dataset.mode){update(s=>{s.mode=b.dataset.mode;},{message:'已切换，另一种宝图草稿会保留'});return;}
      if(b.dataset.view){view=b.dataset.view;page.scrollTop=0;render();return;}
      if(b.dataset.add){const item=items().find(x=>x.id===b.dataset.add);if(!item)return;if(item.cash){const more=page.querySelector('.tr-add-more');more.open=true;const f=more.querySelector('form');f.elements.name.value='梦幻币';f.elements.category.value='现金';f.elements.source.value=quickSource;f.elements.quantity.value=1;f.elements.realized.checked=true;f.elements.cash.checked=true;f.elements.price.focus({preventScroll:true});page.querySelector('.tr-record-tools').scrollTop=0;tell('请填写实际收到的现金金额（万）后添加');return;}const known=reference(item).known;update(s=>append(s,item),{message:known?'已添加 '+item.name:'已添加 '+item.name+'，尚未设置单价，请在明细中填写'});return;}
      if(b.dataset.event){update(s=>{const rec=s.drafts[s.mode],found=rec.events.find(e=>e.name===b.dataset.event);if(found)found.count++;else rec.events.push({name:b.dataset.event,count:1});});return;}
      if(b.dataset.removeCustom){if(confirm('只移除此快捷物品？历史记录和已有明细不会删除。'))update(s=>{s.customItems=s.customItems.filter(x=>x.id!==b.dataset.removeCustom);});return;}
      const action=b.dataset.action,index=Number(b.dataset.index);
      if(action==='back'){close();return;}
      if(action==='remove-row')update(s=>s.drafts[s.mode].rows.splice(index,1));
      if(action==='event-minus')update(s=>{const rec=s.drafts[s.mode];if(--rec.events[index].count===0)rec.events.splice(index,1);});
      if(action==='clear-filter'){filter={mode:'',map:'',date:''};render();}
      if(action==='settle'){if(!refreshCost(true))return;if(!d().rows.length&&!confirm('尚未登记产出，按收益 0 结算本轮？'))return;update(s=>{core.settle(s);view='history';filter={mode:'',map:'',date:''};},{sync:true,message:'本轮已保存；已到账收入和成本已更新到五开总账'});}
      if(action==='edit'){const rec=state.history.find(x=>x.id===b.dataset.id);if(!rec)return;const old=state.drafts[rec.mode];if((old.rows.length||old.quantity||old.id)&&!confirm('当前同类型草稿尚未结算，替换草稿以修改历史？'))return;update(s=>{s.mode=rec.mode;s.drafts[rec.mode]=clone(rec);view='run';},{message:'正在修改历史；保存后更新原记录，不会重复记账'});page.scrollTop=0;}
      if(action==='cancel-edit')update(s=>{s.drafts[s.mode]=core.fresh(s.mode);},{message:'已取消修改，原历史记录保持不变'});
      if(action==='delete'&&confirm('删除这轮挖图记录，并移除其在五开总账中的收支？'))update(s=>{s.history=s.history.filter(x=>x.id!==b.dataset.id);Object.keys(s.drafts).forEach(mode=>{if(s.drafts[mode].id===b.dataset.id)s.drafts[mode]=core.fresh(mode);});},{sync:true});
      if(action==='export')download();if(action==='import')page.querySelector('[data-import]').click();
    });
    page.addEventListener('input',event=>{if(event.target.matches('[data-field="unitCost"],[data-field="quantity"]'))refreshCost(true);});
    page.addEventListener('change',async event=>{const el=event.target;
      if(['unitCost','quantity'].includes(el.dataset.field))refreshCost(true);
      else if(el.dataset.field){const numeric=['extraCost','minutes'].includes(el.dataset.field);update(s=>{s.drafts[s.mode][el.dataset.field]=numeric?num(el.value,'本轮信息',el.dataset.field==='minutes'):el.value;},{redraw:false});}
      if(el.dataset.row!==undefined){const index=Number(el.dataset.row),prop=el.dataset.prop;const saved=update(s=>{const row=s.drafts[s.mode].rows[index];row.priceMode=core.rowPriceMode(row);if(prop==='realized')row.realized=row.cash||el.checked;else if(prop==='quantity'||prop==='price')row[prop]=num(el.value,'物品'+prop,prop==='quantity');else row[prop]=el.value.trim();s.prices[JSON.stringify([s.mode,row.name,row.source])]=row.price;},{redraw:true});if(saved&&prop==='price'){const row=d().rows[index];publishPrice(row,row.price);}}
      if(el.hasAttribute('data-quick-source')){quickSource=el.value;render();}
      if(el.dataset.filter){filter[el.dataset.filter]=el.value;render();}
      if(el.matches('[data-form="row"] [name="name"],[data-form="row"] [name="category"],[data-form="row"] [name="source"]')){const f=el.form;f.elements.price.value=reference({name:f.elements.name.value.trim(),category:f.elements.category.value.trim(),cash:f.elements.cash.checked},f.elements.source.value).price;}
      if(el.matches('[data-import]')&&el.files[0]){try{const file=el.files[0];if(file.size>5*1024*1024)throw new Error('备份不能超过 5 MB');const next=core.validateState(JSON.parse((await file.text()).replace(/^\uFEFF/,'')));if(!confirm('用此备份替换所有挖图草稿、历史与价格，并重新计算总账？'))return;localStorage.setItem(KEY,JSON.stringify(next));state=next;root.dispatchEvent(new CustomEvent('ring-ledger-changed'));render();tell('挖图数据已恢复');}catch(e){tell('未恢复：'+e.message,true);}finally{el.value='';}}
    });
    page.addEventListener('submit',event=>{
      event.preventDefault();const f=event.target,data=Object.fromEntries(new FormData(f));
      if(f.dataset.form==='row'){
        let item,price;const saved=update(s=>{const cash=!!data.cash,q=num(data.quantity,'数量',true);if(!q)throw new Error('数量至少为 1');if(cash&&q!==1)throw new Error('现金数量请填 1，单价填写总金额');item={name:data.name.trim(),category:data.category.trim(),cash};price=num(data.price,'单价');append(s,item,{source:data.source,quantity:q,price,realized:!!data.realized,cash});},{message:'产出已添加，参考价格已记住'});
        if(saved)publishPrice(item,price);
      }
      if(f.dataset.form==='custom')update(s=>{const name=data.name.trim();if(!name)throw new Error('请填写名称');if(s.customItems.some(x=>x.name===name&&x.mode===data.mode))throw new Error('这个自定义快捷项已存在');s.customItems.push({id:uid('custom'),name,category:data.category.trim(),mode:data.mode,cash:false});},{message:'已保存为快捷物品'});
    });
    root.addEventListener('shared-prices-changed',refreshReferences);
  }
  function open(){try{state=read();}catch(e){alert('挖图数据读取失败，原数据已保留：'+e.message);return;}if(!page){page=document.createElement('section');page.id='treasure-project';page.setAttribute('aria-label','挖图记账');document.body.append(page);bind();}root.ringProject?.hide();root.sceneProject?.hide();root.toolboxProject?.hide();root.supportProject?.hide();document.getElementById('app').hidden=true;page.hidden=false;root.projectNavigation?.select('treasure');render();}
  function hide(){if(page)page.hidden=true;}
  function close(){hide();document.getElementById('app').hidden=false;root.projectNavigation?.select('accounting');}
  root.treasureProject={open,hide,close};
})(window);
